import type { Connection, RowDataPacket } from "mysql2/promise";

export type BackupGateRecord = {
  id: string;
  status: string;
  completedAt: string | Date | null;
  artifactKey: string | null;
  fileSize: number | string | null;
  archiveSha256: string | null;
  manifestJson: string | null;
};

export const BACKUP_MAX_AGE_MS = 24 * 60 * 60 * 1000;

/**
 * Only a recently completed and deeply verified backup qualifies as a release gate.
 * The verification metadata is generated by the existing H2 backup service after
 * validating the remote encrypted archive. The DB record alone does not prove a
 * complete restoration; recovery tests remain a separate deployment gate.
 */
export function inspectSiteSecurityBackup(
  record: BackupGateRecord | null | undefined,
  expectedId: string,
  now = Date.now(),
): string[] {
  const errors: string[] = [];
  if (!/^[a-f0-9]{48}$/i.test(expectedId)) return ["ID de backup inválido"];
  if (!record || record.id !== expectedId) return ["Backup informado não encontrado"];
  if (record.status !== "completed") errors.push("Backup não está concluído");
  if (!record.artifactKey || record.artifactKey.trim().length === 0) errors.push("Artefato remoto ausente");
  const size = Number(record.fileSize);
  if (!Number.isSafeInteger(size) || size <= 0) errors.push("Tamanho de backup inválido");
  if (!/^[a-f0-9]{64}$/i.test(record.archiveSha256 || "")) errors.push("SHA-256 de backup inválido");
  const completed = record.completedAt ? new Date(record.completedAt).getTime() : NaN;
  if (!Number.isFinite(completed) || completed > now + 2 * 60_000 ||
      now - completed > BACKUP_MAX_AGE_MS) errors.push("Backup não foi concluído nas últimas 24 horas");
  let verified: Record<string, unknown> | undefined;
  try {
    const manifest = JSON.parse(record.manifestJson || "{}") as Record<string, unknown>;
    const remote = manifest.remoteVerification;
    if (remote && typeof remote === "object" && !Array.isArray(remote)) {
      verified = remote as Record<string, unknown>;
    }
  } catch { errors.push("Manifesto do backup inválido"); }
  if (verified?.status !== "verified") errors.push("Integridade profunda do backup não verificada");
  if (!Number.isFinite(Number(verified?.bytes)) || Number(verified?.bytes) !== size) {
    errors.push("Tamanho da verificação remota não confere");
  }
  if (typeof verified?.sha256 !== "string" ||
      verified.sha256.toLowerCase() !== (record.archiveSha256 || "").toLowerCase()) {
    errors.push("SHA-256 da verificação remota não confere");
  }
  const checkedAt = typeof verified?.verifiedAt === "string" ? Date.parse(verified.verifiedAt) : NaN;
  if (!Number.isFinite(checkedAt) || checkedAt < completed - 60_000 || checkedAt > now + 2 * 60_000) {
    errors.push("Verificação remota não corresponde a este backup");
  }
  return errors;
}

/** Safe read-only query on the existing backup registry; no secrets or payloads logged. */
export async function readSiteSecurityBackup(
  conn: Connection,
  id: string,
): Promise<BackupGateRecord | null> {
  if (!/^[a-f0-9]{48}$/i.test(id)) return null;
  const [rows] = await conn.query<RowDataPacket[]>(
    "SELECT id, status, completedAt, artifactKey, fileSize, archiveSha256, manifestJson FROM systemBackups WHERE id = ? LIMIT 1",
    [id],
  );
  return rows.length ? rows[0] as BackupGateRecord : null;
}
